    print(f"Exp{e} dose={dose} yield_mean={df['CropYield'].mean():.2f} sd={df['CropYield'].std():.2f}")
# also earlier iron experiments if any
for e in [1,2,3,4,5,6]:
    try:
        df = pd.read_csv(eval(f"experiment_{e}_csv"))
        cols = [c for c in df.columns if 'iron' in c.lower() or 'fe' in c.lower()]
        if cols:
            print(f"Exp{e} cols={cols} dose={df[cols[0]].iloc[0] if len(df)>0 else 'na'} yield={df['CropYield'].mean():.2f}")
        else:
            print(f"Exp{e} no iron col; yield={df['CropYield'].mean():.2f}; cols={list(df.columns)}")
    except Exception as ex:
        print(e, ex)
